/** single byte => name, for errors and for `SEE`-style rendering. */
export function jf_op_name(n) {
  if (n <= JF_PUSH_MAX) return `PUSH${n}`
  if (n >= JF_ESC0) return `BANK:${JF_BANK[n] ?? '?'}`
  return REV.get(n) ?? `JF_UNKNOWN_${hex2(n)}`
}
